{
  "name": "@groundtrack/opencode-plugin",
  "version": "0.1.0",
  "description": "OpenCode plugin that enriches Groundtrack MCP tool calls with session metadata.",
  "keywords": [
    "groundtrack",
    "mcp",
    "opencode",
    "opencode-plugin"
  ],
  "license": "MIT",
  "files": [
    "dist/",
    "LICENSE"
  ],
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    },
    "./package.json": "./package.json"
  },
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@groundtrack/hooks": "^0.1.6"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.18.30",
    "@types/node": "^25.9.1",
    "tsx": "^4.20.5",
    "typescript": "~7.0.2",
    "@groundtrack/typescript": "0.0.0"
  },
  "engines": {
    "node": ">=18"
  },
  "scripts": {
    "build": "tsc -p tsconfig.build.json",
    "lint": "vp lint",
    "test": "node --import tsx --test test/*.test.ts",
    "typecheck": "tsc -p tsconfig.json"
  }
}
